corrected_code:
import { json, LoaderFunctionArgs } from '@remix-run/node';
import { kyselyDb } from '~/kysely.server';
import { getSessionUser } from '~/auth.server';

export async function loader({ request, params }: LoaderFunctionArgs) {
  const user = await getSessionUser(request);
  if (!user) throw new Response('Unauthorized', { status: 401 });

  const isSelf = user.employeeId === params.empId;
  const isHR = user.roles?.includes('COMPENSATION_ADMIN');
  if (!isSelf && !isHR) {
    throw new Response('Forbidden: access denied to compensation data', { status: 403 });
  }

  const compensation = await kyselyDb
    .selectFrom('employee_salaries')
    .selectAll()
    .where('employee_id', '=', params.empId!)
    .executeTakeFirst();

  if (!compensation) throw new Response('Record not found', { status: 404 });
  return json({ compensation });
}
